Inductive kz : Type :=
| KZRange (e lo hi : Z)              (* [comment removed for export] *)
| KZAlign (e m : Z)                  (* [comment removed for export] *)
| KZDisj (a1 n1 a2 n2 : Z)           (* [comment removed for export] *)
| KZWr (a n : Z)                     (* [comment removed for export] *)
| KZImg (lo hi : Z)                  (* [comment removed for export] *)
| KZWord (a : Z) (w : nat) (v : Z)   (* [comment removed for export] *)
| KZZero (a n : Z)                   (* [comment removed for export] *)
| KZIdx (tl T : Z)                   (* [comment removed for export] *)
| KZTab (a n st : Z) (fs : list (Z * Z * Z))
                                     (* [comment removed for export] *)
| KZShZ (off a n : Z).               (* [comment removed for export] *)

(* [comment removed for export] *)
Inductive zk : Type :=
| ZKRange (e : zexp) (lo hi : Z) | ZKAlign (e : zexp) (m : Z) | ZKDisj (a1 n1 a2 n2 : zexp)
| ZKWr (a n : zexp) | ZKImg (lo hi : Z) | ZKWord (a : zexp) (w : nat) (v : zexp) | ZKZero (a n : zexp) | ZKIdx (tl T : zexp)
| ZKTab (a n : zexp) (st : Z) (fs : list (Z * Z * Z))
| ZKShZ (off : Z) (a n : zexp).

Definition zsa (z : zexp) : saddr := to_saddr (lnorm (zx z)) 0.
Definition zle (z : zexp) : expr := lnorm (zx z).

Definition zk_ent (k : zk) : kentry :=
  match k with
  | ZKRange e lo hi => KRange (zle e) lo hi
  | ZKAlign e m => KAlign (zle e) m
  | ZKDisj a1 n1 a2 n2 => KDisj (zsa a1) (zle n1) (zsa a2) (zle n2)
  | ZKWr a n => KWr (zsa a) (zle n)
  | ZKImg lo hi => KImg lo hi
  | ZKWord a w v => KWord (zsa a) w (zle v)
  | ZKZero a n => KZero (zsa a) (zle n)
  | ZKIdx _ _ => KRange (ELit 0) 0 0      (* [comment removed for export] *)
  | ZKTab _ _ _ _ => KRange (ELit 0) 0 0  (* [comment removed for export] *)
  | ZKShZ _ _ _ => KRange (ELit 0) 0 0    (* [comment removed for export] *)
  end.

(* [comment removed for export] *)
Definition zreg : Type := (zexp * zexp)%type.
Definition zr_reg (r : zreg) : saddr * expr := (zsa (fst r), zle (snd r)).

