Section Bulk.
Variable segs : list Segment.

Definition kx_rcov (kn : list kentry) (rr : list (saddr * expr)) (a : saddr) (n : nat) : bool :=
  existsb (fun r => zf_covers kn (a_base a) (a_off a) n (a_base (fst r)) (a_off (fst r)) (snd r)) rr.

Definition region_ok (m : word -> option byte) (E : env) (r : saddr * expr) : Prop :=
  0 <= estart E (fst r) /\ estart E (fst r) + elenZ E (snd r) <= 2^64 /\
  forall i, 0 <= i < elenZ E (snd r) -> mrd segs m (Z_to_bv 64 (estart E (fst r) + i)) <> None.

Lemma kx_rcov_sound : forall m E M kn rr a n,
  know_ok segs E M kn -> Forall (region_ok m E) rr -> (1 <= n <= 8)%nat ->
  kx_rcov kn rr a n = true -> exists bs, rdn segs m (adenot E a) n = Some bs.
Proof.
