(* [comment removed for export] *)
Definition rb_ok (na : nat) (reads : list (saddr * nat * bool)) (kn : list kentry) (rr : list (saddr * expr)) (s : sidecond) : bool :=
  match s with
  | SCReadBase a n sx (EVar j) =>
      Nat.leb na j && Nat.leb 1 n && Nat.leb n 8 &&
      match nth_error reads (j - na) with
      | Some (a', n', sx') => saddr_eqb a a' && Nat.eqb n n' && Bool.eqb sx sx' && kx_rcov kn rr a n
      | None => false
      end
  | _ => true
  end.

Definition is_rb (s : sidecond) : bool := match s with SCReadBase _ _ _ (EVar _) => true | _ => false end.

(* [comment removed for export] *)
Definition sc_auto (na : nat) (reads : list (saddr * nat * bool)) (kn : list kentry) (rr : list (saddr * expr)) (s : sidecond) : bool :=
  match s with
  | SCReadBase _ _ _ (EVar _) => rb_ok na reads kn rr s
  | SCFlat a (ELit k) => Z.leb 1 k && Z.leb k 8 && kx_rcov kn rr a (Z.to_nat k)
  | _ => false
  end.

Lemma kx_rcov_flat : forall m E M kn rr a n,
  know_ok segs E M kn -> Forall (region_ok m E) rr -> (1 <= n <= 8)%nat ->
  kx_rcov kn rr a n = true -> flat E a (Z.of_nat n).
