Theorem kx_scs_bulk : forall m ws reads kn rr scs,
  let E := kx_env ws (kx_vals segs m ws reads) in
  reads_scoped (length ws) reads = true ->
  know_ok segs E m kn -> Forall (region_ok m E) rr ->
  scs_denot segs m E (List.filter (fun s => negb (sc_auto (length ws) reads kn rr s)) scs) ->
  scs_denot segs m E scs.
Proof.
