(* [comment removed for export] *)
Fixpoint rb_find (j : nat) (scs : list sidecond) : option (saddr * nat * bool) :=
  match scs with
  | [] => None
  | SCReadBase a n sx (EVar k) :: rest => if Nat.eqb j k then Some (a, n, sx) else rb_find j rest
  | _ :: rest => rb_find j rest
  end.
Fixpoint rb_collect (fuel : nat) (j : nat) (scs : list sidecond) : list (saddr * nat * bool) :=
  match fuel with
  | O => []
  | S f => match rb_find j scs with Some r => r :: rb_collect f (S j) scs | None => [] end
  end.
Definition kx_reads_of (na : nat) (scs : list sidecond) : list (saddr * nat * bool) := rb_collect (length scs) na scs.

(* [comment removed for export] *)
Fixpoint read_ranges (j : nat) (reads : list (saddr * nat * bool)) : list kentry :=
  match reads with
  | [] => []
  | (a, n, sx) :: rest =>
      (if (negb sx && Nat.ltb n 8)%bool then [KRange (EVar j) 0 (2 ^ (8 * Z.of_nat n) - 1)] else [])
      ++ read_ranges (S j) rest
  end.

(* [comment removed for export] *)
Lemma kx_rd_bytes_at : forall m E a n A bs, (1 <= n)%nat ->
  bytes_at segs m A bs -> A <= estart E a -> estart E a + Z.of_nat n <= A + Z.of_nat (length bs) ->
  exists bs', rdn segs m (adenot E a) n = Some bs'.
Proof.
