Lemma read_ranges_ok : forall m ws reads,
  let E := kx_env ws (kx_vals segs m ws reads) in
  reads_scoped (length ws) reads = true ->
  forall j0 rs, (forall i r, nth_error rs i = Some r -> nth_error reads (j0 - length ws + i) = Some r) ->
  (length ws <= j0)%nat ->
  know_ok segs E m (read_ranges j0 rs).
Proof.
