(* [comment removed for export] *)
Fixpoint srl_with (s0 : expr) (e : expr) (acc : list expr) : list expr :=
  match e with
  | EAlu ALU_SRL x s =>
      let acc' := srl_with s0 s (srl_with s0 x acc) in
      if expr_eqb s s0 then (if existsb (expr_eqb e) acc' then acc' else e :: acc') else acc'
  | EAlu _ a b | EAluw _ a b | EMd _ a b | EMdw _ a b => srl_with s0 b (srl_with s0 a acc)
  | EExt _ _ _ a => srl_with s0 a acc
  | _ => acc
  end.
Definition srl_sc (s0 : expr) (acc : list expr) (sc : sidecond) : list expr :=
  match sc with
  | SCReadBase a _ _ _ => srl_with s0 (a_base a) acc
  | SCFlat a n => srl_with s0 (a_base a) acc
  | SCDisj a1 _ a2 _ => srl_with s0 (a_base a2) (srl_with s0 (a_base a1) acc)
  | SCInside a1 _ a2 _ => srl_with s0 (a_base a2) (srl_with s0 (a_base a1) acc)
  | SCStoreOk a _ => srl_with s0 (a_base a) acc
  | _ => acc
  end.
Definition idx_fact (T : expr) (idx : expr) : kentry := KRange (lnorm (EAlu ALU_SUB (EAlu ALU_SUB T idx) (ELit 1))) 0 4095.
Definition idx_facts (T s0 : expr) (scs : list sidecond) : list kentry :=
  map (idx_fact T) (fold_left (srl_sc s0) scs []).

Lemma idx_fact_ok : forall E m T x s tl,
  edenot E T = Z_to_bv 64 (2 ^ tl) -> edenot E s = Z_to_bv 64 (64 - tl) -> 1 <= tl <= 12 ->
  kentry_ok segs E m (idx_fact T (EAlu ALU_SRL x s)).
Proof.
