(* [comment removed for export] *)
(* [comment removed for export] *)
Definition ztab : Type := (saddr * expr * Z * list (Z * Z * Z))%type.

Fixpoint find_field (off : Z) (fs : list (Z * Z * Z)) : option (Z * Z) :=
  match fs with
  | [] => None
  | (o, lo, hi) :: r => if Z.eqb o off then Some (lo, hi) else find_field off r
  end.

Definition tab_rule (kn : list kentry) (t : ztab) (a : saddr) : option (Z * Z) :=
  let '(ta, len, st, fs) := t in
  if zf_covers kn (a_base a) (a_off a) 1 (a_base ta) (a_off ta) len then
    let k := Z.log2 st in
    if (Z.eqb st (2 ^ k) && Z.leb 0 k && Z.leb k 64 &&
        (Z.eqb k 0 || Z.leb k (ealign kn (lnorm (EAlu ALU_SUB (a_base a) (a_base ta))))))%bool
    then find_field ((a_off a - a_off ta) mod st) fs
    else None
  else None.

Fixpoint tabs_rule (kn : list kentry) (ts : list ztab) (a : saddr) : option (Z * Z) :=
  match ts with
  | [] => None
  | t :: r => match tab_rule kn t a with Some x => Some x | None => tabs_rule kn r a end
  end.

Fixpoint tab_ranges (kn : list kentry) (ts : list ztab) (j : nat) (reads : list (saddr * nat * bool)) : list kentry :=
  match reads with
  | [] => []
  | (a, n, sx) :: rest =>
      (if (negb sx && Nat.eqb n 1)%bool then
         match tabs_rule kn ts a with Some (lo, hi) => [KRange (EVar j) lo hi] | None => [] end
       else [])
      ++ tab_ranges kn ts (S j) rest
  end.

(* [comment removed for export] *)
Definition ztab_fact (m : word -> option byte) (A N st : Z) (fs : list (Z * Z * Z)) : Prop :=
  forall z, A <= z < A + N -> forall lo hi, find_field ((z - A) mod st) fs = Some (lo, hi) ->
    exists b, rdn segs m (Z_to_bv 64 z) 1 = Some [b] /\ lo <= bv_unsigned b <= hi.

Definition tab_ok (m : word -> option byte) (E : env) (t : ztab) : Prop :=
  let '(ta, len, st, fs) := t in ztab_fact m (estart E ta) (elenZ E len) st fs.

Lemma tab_rule_ok : forall m E M kn t a lo hi,
  know_ok segs E M kn -> tab_ok m E t -> tab_rule kn t a = Some (lo, hi) ->
  lo <= bv_unsigned (rdval segs m (adenot E a) 1 false) <= hi.
Proof.
