(* [comment removed for export] *)
Fixpoint tab_img_chk (A : Z) (st : Z) (fs : list (Z * Z * Z)) (z : Z) (k : nat) : bool :=
  match k with
  | O => true
  | S k' =>
      (ro_addr segs (Z_to_bv 64 z) &&
       match Lib.PropExec.seg_rom segs (Z_to_bv 64 z) with
       | Some b => match find_field ((z - A) mod st) fs with
                   | Some (lo, hi) => Z.leb lo (bv_unsigned b) && Z.leb (bv_unsigned b) hi
                   | None => true
                   end
       | None => false
       end && tab_img_chk A st fs (z + 1) k')%bool
  end.

Lemma tab_img_chk_ok : forall m A st fs, mem_inv segs m -> forall k z, tab_img_chk A st fs z k = true ->
  forall y, z <= y < z + Z.of_nat k -> forall lo hi, find_field ((y - A) mod st) fs = Some (lo, hi) ->
    exists b, rdn segs m (Z_to_bv 64 y) 1 = Some [b] /\ lo <= bv_unsigned b <= hi.
Proof.
