(* [comment removed for export] *)
Definition zshz : Type := (Z * saddr * expr)%type.     (* [comment removed for export] *)

Definition shz_rule (kn : list kentry) (t : zshz) (a : saddr) : bool :=
  let '(off, w, len) := t in
  if Z.eqb (a_off a) off then
    match a_base a with
    | EAlu ALU_SRL X (ELit 3) => zf_covers kn X 0 1 (a_base w) (a_off w) len
    | _ => false
    end
  else false.

Definition shz_any (kn : list kentry) (ts : list zshz) (a : saddr) : bool := existsb (fun t => shz_rule kn t a) ts.

Fixpoint shz_ranges (kn : list kentry) (ts : list zshz) (j : nat) (reads : list (saddr * nat * bool)) : list kentry :=
  match reads with
  | [] => []
  | (a, n, sx) :: rest =>
      (if (Nat.eqb n 1 && shz_any kn ts a)%bool then [KRange (EVar j) 0 0] else [])
      ++ shz_ranges kn ts (S j) rest
  end.

(* [comment removed for export] *)
Definition kshz_fact (m : word -> option byte) (off A N : Z) : Prop :=
  forall x, A <= x < A + N -> m (Z_to_bv 64 (off + Z.shiftr x 3)) = Some (Z_to_bv 8 0).

Definition shz_ok (m : word -> option byte) (E : env) (t : zshz) : Prop :=
  let '(off, w, len) := t in kshz_fact m off (estart E w) (elenZ E len).

Lemma srl3_u : forall x : word, bv_unsigned (alu64 ALU_SRL x (Z_to_bv 64 3)) = Z.shiftr (bv_unsigned x) 3.
