Lemma shz_rule_sound : forall E M kn t a, know_ok segs E M kn -> shz_rule kn t a = true ->
  let '(off, w, len) := t in
  exists x, estart E w <= x < estart E w + elenZ E len /\ adenot E a = Z_to_bv 64 (off + Z.shiftr x 3).
