Lemma shz_any_rd : forall m E M kn ts a, know_ok segs E M kn -> Forall (shz_ok m E) ts -> shz_any kn ts a = true ->
  rdn segs m (adenot E a) 1 = Some [Z_to_bv 8 0].
Proof.
