(* [comment removed for export] *)
Definition rb_ok2 (na : nat) (reads : list (saddr * nat * bool)) (kn : list kentry) (rr : list (saddr * expr))
    (ts : list zshz) (s : sidecond) : bool :=
  match s with
  | SCReadBase a n sx (EVar j) =>
      Nat.leb na j && Nat.leb 1 n && Nat.leb n 8 &&
      match nth_error reads (j - na) with
      | Some (a', n', sx') => saddr_eqb a a' && Nat.eqb n n' && Bool.eqb sx sx' &&
                              (kx_rcov kn rr a n || (Nat.eqb n 1 && shz_any kn ts a))
      | None => false
      end
  | _ => true
  end.

Definition sc_auto2 (na : nat) (reads : list (saddr * nat * bool)) (kn : list kentry) (rr : list (saddr * expr))
    (ts : list zshz) (s : sidecond) : bool :=
  match s with
  | SCReadBase _ _ _ (EVar _) => rb_ok2 na reads kn rr ts s
  | SCFlat a (ELit k) => Z.leb 1 k && Z.leb k 8 && kx_rcov kn rr a (Z.to_nat k)
  | _ => false
  end.

Theorem kx_scs_bulk2 : forall m ws reads kn rr ts scs,
  let E := kx_env ws (kx_vals segs m ws reads) in
  reads_scoped (length ws) reads = true ->
  know_ok segs E m kn -> Forall (region_ok m E) rr -> Forall (shz_ok m E) ts ->
  scs_denot segs m E (List.filter (fun s => negb (sc_auto2 (length ws) reads kn rr ts s)) scs) ->
  scs_denot segs m E scs.
